// This tool builds the exhaustruct linter (https://github.com/GaijinEntertainment/go-exhaustruct)
// against a version of golang.org/x/tools that supports the export data format of the Go version used by Git Town.
// The official exhaustruct release pins an older version of golang.org/x/tools
// that cannot read the export data generated by newer Go versions.
// Remove this tool and go back to "rta exhaustruct" once an exhaustruct release supports the Go version used here.
package main

import (
	"flag"

	"dev.gaijin.team/go/exhaustruct/v5/analyzer"
	"golang.org/x/tools/go/analysis/singlechecker"
)

func main() {
	// go vet passes -unsafeptr to every vettool, register a stub so that flag parsing doesn't fail when invoked via "go vet -vettool"
	flag.Bool("unsafeptr", false, "")
	singlechecker.Main(analyzer.NewAnalyzer())
}
